func poly_area(p: PackedVector2Array) -> float:
	var a = 0.0
	var n = p.size()
	for i in range(n):
		var j = (i+1)%n
		a += p[i].x*p[j].y - p[j].x*p[i].y
	return absf(a)/2.0

func tris_area(tris: Array) -> float:
	var total = 0.0
	for t in tris:
		total += poly_area(t)
	return total

